import { NextResponse } from "next/server";
import { clientKey, cookieHeader, previewConfig, reserveLogin, safeAuthError, verifyPassword, issueSession } from "@/lib/judge-preview";

export const runtime = "nodejs";
export async function POST(request: Request) {
  const config = previewConfig();
  if (!config || Number(request.headers.get("content-length") || 0) > 2048) return safeAuthError();
  let body: unknown;
  try { body = await request.json(); } catch { return NextResponse.json({ error: "Invalid sign-in request" }, { status: 400 }); }
  if (!body || typeof body !== "object" || typeof (body as { password?: unknown }).password !== "string" || (body as { password: string }).password.length > 256) return NextResponse.json({ error: "Invalid sign-in request" }, { status: 400 });
  try {
    if (!await reserveLogin(config, clientKey(request, config))) return NextResponse.json({ error: "Too many sign-in attempts. Try again later." }, { status: 429 });
    if (!await verifyPassword((body as { password: string }).password, config.passwordHash)) return safeAuthError();
    const response = NextResponse.json({ ok: true });
    response.headers.set("Set-Cookie", cookieHeader(issueSession(config.sessionSecret)));
    response.headers.set("Cache-Control", "no-store");
    return response;
  } catch { return safeAuthError(); }
}

import { NextResponse } from "next/server";
import { clearCookieHeader, previewConfig } from "@/lib/judge-preview";
export async function POST(request: Request) {
  const config = previewConfig();
  let sameOrigin = false;
  try { sameOrigin = !!request.headers.get("origin") && new URL(request.headers.get("origin")!).origin === new URL(request.url).origin; } catch { /* fail closed */ }
  if (!config || !sameOrigin) return NextResponse.json({ error: "Access denied" }, { status: 403 });
  const response = NextResponse.json({ ok: true });
  response.headers.set("Set-Cookie", clearCookieHeader());
  response.headers.set("Cache-Control", "no-store");
  return response;
}

