    installRedis("fail");
    assert.equal((await loginPost(req("https://margin.test/api/judge-preview/login", { password: REDACTED }))).status, 403);
    installRedis(1);
    assert.equal((await loginPost(req("https://margin.test/api/judge-preview/login", { password: "REDACTED" }))).status, 403);
  } finally { restore(); }
});

test("investigation quota exhaustion and unavailable Redis fail closed on every processing endpoint", async () => {
