import { NextResponse } from "next/server";
import { extractPdfPages } from "@/lib/pdf-ingestion";
import { isDemoMode } from "@/lib/demo-mode";
import { authorizeSession, reserveProcessing } from "@/lib/judge-preview";
import { boundedBodyError, readBoundedBody } from "@/lib/bounded-request-body";

export const runtime = "nodejs";
const MAX_PDF_BYTES = 10 * 1024 * 1024;

export async function POST(request: Request): Promise<Response> {
  if (isDemoMode()) return NextResponse.json({ error: "PDF ingestion is disabled in synthetic demo mode" }, { status: 403 });
  const session = authorizeSession(request);
  if (session.response) return session.response;
  const bounded = await readBoundedBody(request, MAX_PDF_BYTES + 64 * 1024);
  if (!bounded.ok) return boundedBodyError(bounded.reason, MAX_PDF_BYTES + 64 * 1024);
  const access = await reserveProcessing(request, session, "upload");
  if (access.response) return access.response;
  try {
    const contentType = request.headers.get("content-type");
    if (!contentType?.toLowerCase().startsWith("multipart/form-data;")) return NextResponse.json({ error: "Upload a PDF multipart request" }, { status: 400 });
    const multipartBytes = new Uint8Array(bounded.bytes.byteLength);
    multipartBytes.set(bounded.bytes);
    const boundedRequest = new Request(request.url, { method: "POST", headers: { "Content-Type": contentType }, body: multipartBytes });
    const form = await boundedRequest.formData();
    const file = form.get("file");
    if (!(file instanceof File)) {
      return NextResponse.json({ error: "Upload a PDF in the 'file' field" }, { status: 400 });
    }
    if (file.size > MAX_PDF_BYTES) {
      return NextResponse.json({ error: "PDF exceeds the 10MB limit" }, { status: 413 });
    }
    if (file.type && file.type !== "application/pdf") {
      return NextResponse.json({ error: "File must have PDF content type" }, { status: 415 });
    }
    const pages = await extractPdfPages(new Uint8Array(await file.arrayBuffer()));
    return NextResponse.json({ pages });
  } catch (error) {
  const message =
    error instanceof Error ? error.message : "PDF ingestion failed";

  const clientError = /empty|limit|not a PDF/i.test(message);
  const safeMessage = /empty/i.test(message) ? "PDF is empty" : /limit/i.test(message) ? "PDF exceeds the configured size or page limit" : /not a PDF/i.test(message) ? "Uploaded file is not a PDF" : "PDF could not be read";

  return NextResponse.json(
    { error: safeMessage },
    { status: clientError ? 400 : 422 }
  );
  }
}
/** PDF text extraction only. Extracted text is untrusted and must be reviewed/mapped
 * into the existing JSON schema before it can enter the deterministic audit flow.
 */
export type PdfPageText = { page: number; text: string };

const MAX_PDF_BYTES = 10 * 1024 * 1024;
const MAX_PDF_PAGES = 250;

export async function extractPdfPages(input: Uint8Array): Promise<PdfPageText[]> {
  if (input.byteLength === 0) throw new Error("PDF is empty");
  if (input.byteLength > MAX_PDF_BYTES) throw new Error("PDF exceeds the 10MB limit");
  if (new TextDecoder().decode(input.subarray(0, 5)) !== "%PDF-") {
    throw new Error("Uploaded file is not a PDF");
  }

  const pdfjs = await import("pdfjs-dist/legacy/build/pdf.mjs");
  const loadingTask = pdfjs.getDocument({ data: new Uint8Array(input) });
  const document = await loadingTask.promise;
  if (document.numPages > MAX_PDF_PAGES) {
    await loadingTask.destroy();
    throw new Error("PDF exceeds the 250 page limit");
  }
  const pages: PdfPageText[] = [];
  try {
    for (let pageNumber = 1; pageNumber <= document.numPages; pageNumber++) {
      const page = await document.getPage(pageNumber);
      const content = await page.getTextContent();
      const text = content.items
        .filter((item): item is typeof item & { str: string } => "str" in item)
        .map(item => item.str)
        .join(" ")
        .replace(/\s+/g, " ")
        .trim();
      pages.push({ page: pageNumber, text });
      page.cleanup();
    }
  } finally {
    await loadingTask.destroy();
  }
  return pages;
}
export type BoundedBody = { ok: true; bytes: Uint8Array } | { ok: false; reason: "too_large" | "invalid_length" };

/** Read at most `maxBytes` from the actual stream. Content-Length is only an early hint. */
export async function readBoundedBody(request: Request, maxBytes: number): Promise<BoundedBody> {
  const declared = request.headers.get("content-length");
  if (declared !== null) {
    if (!/^\d+$/.test(declared)) return { ok: false, reason: "invalid_length" };
    if (Number(declared) > maxBytes) return { ok: false, reason: "too_large" };
  }
  if (!request.body) return declared && Number(declared) !== 0 ? { ok: false, reason: "invalid_length" } : { ok: true, bytes: new Uint8Array() };

  const reader = request.body.getReader();
  const chunks: Uint8Array[] = [];
  let total = 0;
  try {
    for (;;) {
      const { done, value } = await reader.read();
      if (done) break;
      total += value.byteLength;
      if (total > maxBytes) {
        await reader.cancel();
        return { ok: false, reason: "too_large" };
      }
      chunks.push(value);
    }
  } finally { reader.releaseLock(); }

  if (declared !== null && Number(declared) !== total) return { ok: false, reason: "invalid_length" };
  const bytes = new Uint8Array(total);
  let offset = 0;
  for (const chunk of chunks) { bytes.set(chunk, offset); offset += chunk.byteLength; }
  return { ok: true, bytes };
}

export function boundedBodyError(reason: "too_large" | "invalid_length", maxBytes: number) {
  return Response.json({ error: reason === "too_large" ? `Request payload exceeds the ${maxBytes} byte limit` : "Invalid request length" }, { status: reason === "too_large" ? 413 : 400 });
}

